 receiptCalculation: `static decimal CalculateTotal(decimal amount) =>
    amount >= 1000m ? amount * 0.9m : amount;`,
 priceChange: `static decimal CalculateTotal(decimal amount) =>
    amount >= 1500m ? amount * 0.8m : amount;`,
